/* From Uiverse.io by vinodjangid07  - Tags: hover, checkbox, toggle, save, hover effect, pin, bookmark */
.__UIV_SCOPE__ .container input {
  display: none;
}
.__UIV_SCOPE__ .pin {
  width: 15px;
  height: auto;
  transform: rotate(35deg);
}
.__UIV_SCOPE__ .container {
  width: 45px;
  height: 45px;
  background-color: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: 10px;
}
.__UIV_SCOPE__ .container input:checked ~ .pin {
  fill: rgb(179, 139, 255);
  stroke: white;
}
.__UIV_SCOPE__ .container input:checked ~ .pin line {
  stroke: rgb(179, 139, 255);
}
.__UIV_SCOPE__ .container input:checked ~ .pin path {
  stroke: rgb(179, 139, 255);
}
.__UIV_SCOPE__ .container:hover {
  background-color: rgb(244, 238, 255);
  box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.041);
}
.__UIV_SCOPE__ .container:active {
  transform: scale(0.9);
}
